import java.net.URLEncoder
class ManagerActivity:AppCompatActivity(){private lateinit var root:LinearLayout;private var manager="";private var managerToken="";private var drivers=JSONArray();private var vehicles=JSONArray();private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt();private fun color(id:Int)=getColor(id);private fun shape(fill:Int,r:Int=18,stroke:Int?=null)=GradientDrawable().apply{setColor(fill);cornerRadius=dp(r).toFloat();stroke?.let{setStroke(dp(1),it)}};override fun onCreate(b:Bundle?){super.onCreate(b);root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(20),dp(52),dp(20),dp(28))};setContentView(ScrollView(this).apply{setBackgroundColor(color(R.color.app_background));addView(root)});showLogin()};private fun tv(s:String,z:Float=16f,p:Boolean=true,b:Boolean=false)=TextView(this).apply{text=s;textSize=z;setTextColor(color(if(p)R.color.text_primary else R.color.text_secondary));if(b)setTypeface(typeface,Typeface.BOLD);setPadding(0,dp(4),0,dp(4))};private fun input(h:String)=EditText(this).apply{hint=h;setTextColor(color(R.color.text_primary));setHintTextColor(color(R.color.text_secondary));background=shape(color(R.color.surface_input),14,color(R.color.border_input));setPadding(dp(14),0,dp(14),0);layoutParams=LinearLayout.LayoutParams(-1,dp(54)).apply{topMargin=dp(8)}};private fun button(s:String,p:Boolean=true,a:()->Unit)=Button(this).apply{text=s;isAllCaps=false;setTypeface(typeface,Typeface.BOLD);setTextColor(if(p)Color.WHITE else color(R.color.text_primary));backgroundTintList=android.content.res.ColorStateList.valueOf(color(if(p)R.color.primary else R.color.secondary_button));layoutParams=LinearLayout.LayoutParams(-1,dp(54)).apply{topMargin=dp(10)};setOnClickListener{a()}};private fun card()=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(18),dp(18),dp(18));background=shape(color(R.color.surface),20,color(R.color.border));layoutParams=LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(16)}};private fun label(d:JSONObject):String{val c=d.optInt("code");val r=if(d.isNull("code_label"))"" else d.optString("code_label").trim();return r.takeUnless{it.isBlank()||it.equals("null",true)}?:c.toString()};private fun showLogin(){root.removeAllViews();root.addView(tv("GESTIONE FLOTTA",12f,false,true));root.addView(tv("Area Responsabile",32f,true,true));val c=card();val n=input("Nome responsabile");val p=input("PIN").apply{inputType=InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD};val m=tv("",14f,false,true);c.addView(n);c.addView(p);c.addView(button("Accedi"){Api.postJson("/manager-login",JSONObject().put("name",n.text.toString().trim()).put("pin",p.text.toString().trim())){x,r->runOnUiThread{if(x in 200..299){val o=JSONObject(r);manager=o.optString("name");managerToken=o.optString("token");showDashboard()}else m.text="Accesso non riuscito"}}});c.addView(m);root.addView(c)};private fun showDashboard(){root.removeAllViews();root.addView(tv("GESTIONE FLOTTA",12f,false,true));root.addView(tv("Dashboard",32f,true,true));root.addView(tv("Responsabile: $manager",14f,false));addOverview();loadDriverData();addVehicleCard();addActive();addDamageReports();addDeviceAndHabitual();addDevices();addHistory();addPhotos();root.addView(button("Torna ad autista",false){finish()});root.addView(button("Esci dall'area responsabile",false){manager="";managerToken="";showLogin()})};private fun addOverview(){val c=card();c.addView(tv("PANORAMICA",11f,false,true));val s=tv("Caricamento…",19f,true,true);c.addView(s);root.addView(c);Api.get("/manager-dashboard",managerToken){x,r->runOnUiThread{if(x in 200..299){val q=JSONObject(r).optJSONObject("stats");s.text="${q?.optInt("assigned",0)} chiavi fuori • ${q?.optInt("available",0)} disponibili\n${q?.optInt("drivers",0)} autisti attivi"}}}};private fun loadDriverData(){val c=card();c.addView(tv("SCHEDA COMPLETA AUTISTA",11f,false,true));val sp=Spinner(this);val out=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};c.addView(sp);c.addView(button("Apri scheda autista"){if(drivers.length()==0)return@button;val d=drivers.getJSONObject(sp.selectedItemPosition);Api.get("/manager-driver-card?driver_code=${d.optInt("code")}",managerToken){x,r->runOnUiThread{out.removeAllViews();if(x !in 200..299){out.addView(tv("Autista non trovato",14f,false));return@runOnUiThread};val o=JSONObject(r);val dr=o.getJSONObject("driver");out.addView(tv("${dr.optString("name")} · ${label(dr)}",22f,true,true));out.addView(tv("Furgone abituale: ${dr.optString("habitual_plate").takeUnless{it.isBlank()||it.equals("null",true)}?:"Nessuno"}",15f));val cur=o.optJSONObject("current");out.addView(tv("Mezzo attuale: ${if(cur!=null)cur.optString("plate")+" · "+cur.optString("checkout_at") else "Nessun mezzo assegnato"}",15f));fun section(title:String,a:JSONArray,render:(JSONObject)->String){out.addView(tv(title,12f,false,true));if(a.length()==0)out.addView(tv("Nessun dato",14f,false));for(i in 0 until a.length())out.addView(tv(render(a.getJSONObject(i)),14f))};section("DISPOSITIVI",o.optJSONArray("devices")?:JSONArray()){z->"${z.optString("device_label","Dispositivo")}\nAssociato: ${z.optString("created_at")}"};section("SEGNALAZIONI",o.optJSONArray("reports")?:JSONArray()){z->"${z.optString("status").uppercase()} · ${z.optString("plate")} · ${z.optString("category")}\n${z.optString("description")}"};section("FOTO EFFETTUATE",o.optJSONArray("photos")?:JSONArray()){z->"${z.optString("plate")} · ${z.optString("photo_type")}\n${z.optString("created_at")}"};section("STORICO MEZZI UTILIZZATI",o.optJSONArray("history")?:JSONArray()){z->"${z.optString("plate")}${if(!z.isNull("checkout_km"))" · ${z.optInt("checkout_km")} km" else ""}\nRitiro: ${z.optString("checkout_at")}\nRientro: ${z.optString("return_at").takeUnless{it.isBlank()||it.equals("null",true)}?:"IN CORSO"}"}}}});c.addView(out);root.addView(c);Api.get("/manager-habitual",managerToken){x,r->runOnUiThread{if(x in 200..299){val o=JSONObject(r);drivers=o.optJSONArray("drivers")?:JSONArray();vehicles=o.optJSONArray("vehicles")?:JSONArray();sp.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,(0 until drivers.length()).map{i->val d=drivers.getJSONObject(i);"${d.optString("name")} · ${label(d)}"})}}}};private fun addVehicleCard(){val c=card();c.addView(tv("SCHEDA COMPLETA DEL MEZZO",11f,false,true));val p=input("Targa");val out=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};c.addView(p);c.addView(button("Apri scheda mezzo"){val plate=p.text.toString().trim().uppercase();if(plate.isBlank())return@button;Api.get("/manager-vehicle-card?plate=${URLEncoder.encode(plate,"UTF-8")}",managerToken){x,r->runOnUiThread{out.removeAllViews();if(x !in 200..299){out.addView(tv("Mezzo non trovato",14f,false));return@runOnUiThread};val o=JSONObject(r);val v=o.getJSONObject("vehicle");out.addView(tv("${v.optString("plate")} · ${v.optString("vehicle_type")}",22f,true,true));val last=o.optJSONObject("last_user");out.addView(tv("Ultimo utilizzatore: ${if(last!=null)last.optString("name")+" ("+last.optInt("driver_code")+")" else "Nessuno"}\nKm registrati: ${if(o.isNull("last_km"))"Non ancora disponibili" else o.optInt("last_km")}",15f));val h=o.optJSONArray("habitual_to")?:JSONArray();out.addView(tv("Furgone abituale di: "+if(h.length()==0)"Nessuno" else (0 until h.length()).joinToString(", "){h.getJSONObject(it).optString("name")},15f));val hi=o.optJSONArray("history")?:JSONArray();out.addView(tv("RITIRI / RESTITUZIONI",12f,false,true));for(i in 0 until hi.length()){val z=hi.getJSONObject(i);out.addView(tv("${z.optString("name")} (${z.optInt("driver_code")})\nRitiro: ${z.optString("checkout_at")}\nRientro: ${z.optString("return_at").takeUnless{it.isBlank()||it.equals("null",true)}?:"IN CORSO"}${if(!z.isNull("checkout_km"))"\nKm: ${z.optInt("checkout_km")}" else ""}",14f))}}}});c.addView(out);root.addView(c)};private fun addActive(){val c=card();c.addView(tv("CHIAVI ATTUALMENTE FUORI",11f,false,true));val l=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};c.addView(l);root.addView(c);Api.get("/manager-dashboard",managerToken){x,r->runOnUiThread{if(x in 200..299){val a=JSONObject(r).optJSONArray("active")?:JSONArray();for(i in 0 until a.length()){val z=a.getJSONObject(i);l.addView(tv("${z.optString("name")} · ${z.optString("plate")}",15f,true,true))}}}}};private fun addDamageReports(){val c=card();c.addView(tv("SEGNALAZIONI DANNI / ANOMALIE",11f,false,true));val l=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};c.addView(l);root.addView(c);Api.get("/manager-damage-reports",managerToken){x,r->runOnUiThread{if(x in 200..299){val a=JSONArray(r);for(i in 0 until a.length()){val z=a.getJSONObject(i);l.addView(tv("${z.optString("status").uppercase()} · ${z.optString("plate")} · ${z.optString("category")}\n${z.optString("description")}",14f))}}}}};private fun addDeviceAndHabitual(){val c=card();c.addView(tv("AUTISTI, DISPOSITIVI E FURGONE ABITUALE",11f,false,true));val ds=Spinner(this);val vs=Spinner(this);c.addView(ds);c.addView(vs);val f=tv("",14f,false,true);Api.get("/manager-habitual",managerToken){x,r->runOnUiThread{if(x in 200..299){val o=JSONObject(r);drivers=o.optJSONArray("drivers")?:JSONArray();vehicles=o.optJSONArray("vehicles")?:JSONArray();ds.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,(0 until drivers.length()).map{i->val d=drivers.getJSONObject(i);"${d.optString("name")} · ${label(d)}"});vs.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,listOf("Nessun furgone abituale")+(0 until vehicles.length()).map{i->vehicles.getJSONObject(i).optString("plate")})}}};c.addView(button("Associa questo telefono"){if(drivers.length()>0){val d=drivers.getJSONObject(ds.selectedItemPosition);Api.postJson("/device-register",JSONObject().put("driver_code",d.optInt("code")).put("device_label","${android.os.Build.MANUFACTURER} ${android.os.Build.MODEL}"),managerToken){_,_->}}});c.addView(button("Salva furgone abituale",false){if(drivers.length()>0){val d=drivers.getJSONObject(ds.selectedItemPosition);val p=if(vs.selectedItemPosition==0)"" else vehicles.getJSONObject(vs.selectedItemPosition-1).optString("plate");Api.postJson("/manager-habitual",JSONObject().put("driver_code",d.optInt("code")).put("plate",p),managerToken){x,_->runOnUiThread{f.text=if(x in 200..299)"Furgone abituale aggiornato" else "Errore"}}}});c.addView(f);root.addView(c)};private fun addDevices(){val c=card();c.addView(tv("DISPOSITIVI ASSOCIATI",11f,false,true));root.addView(c);Api.get("/manager-devices",managerToken){x,r->runOnUiThread{if(x in 200..299){val a=JSONArray(r);for(i in 0 until a.length()){val z=a.getJSONObject(i);c.addView(tv("${z.optString("name")} · ${z.optString("device_label")}",14f))}}}}};private fun addHistory(){val c=card();c.addView(tv("STORICO RITIRI E RESTITUZIONI",11f,false,true));val p=input("Targa (facoltativa)");val out=tv("",14f,false);c.addView(p);c.addView(button("Cerca storico",false){Api.get("/manager-history?plate=${URLEncoder.encode(p.text.toString().trim().uppercase(),"UTF-8")}",managerToken){x,r->runOnUiThread{if(x in 200..299){val a=JSONArray(r);out.text=(0 until a.length()).joinToString("\n\n"){i->val z=a.getJSONObject(i);"${z.optString("plate")} · ${z.optString("name")}\n${z.optString("checkout_at")} → ${z.optString("return_at")}"}}}}});c.addView(out);root.addView(c)};private fun addPhotos(){val c=card();c.addView(tv("FOTO MEZZI",11f,false,true));val p=input("Targa (facoltativa)");c.addView(p);c.addView(button("Cerca foto",false){Api.get("/manager-photos?plate=${URLEncoder.encode(p.text.toString().trim().uppercase(),"UTF-8")}",managerToken){_,_->}});root.addView(c)}}